#include "media/Media.h"
#include <fstream>
#include <iostream>
#include <mfapi.h>
int main(int argc,char **argv){CoInitializeEx(nullptr,COINIT_APARTMENTTHREADED);MFStartup(MF_VERSION);int result=0,checks=0;try{
    auto directory=sx::Utf8Path(argv[1])/"build/qa/audio-quality";std::filesystem::create_directories(directory);auto path=directory/"speech-transients.wav";std::ofstream wav(path,std::ios::binary);auto write=[&](auto v){wav.write(reinterpret_cast<char*>(&v),sizeof(v));};wav.write("RIFF",4);write(uint32_t(36+144000*4));wav.write("WAVEfmt ",8);write(uint32_t(16));write(uint16_t(1));write(uint16_t(2));write(uint32_t(48000));write(uint32_t(192000));write(uint16_t(4));write(uint16_t(16));wav.write("data",4);write(uint32_t(144000*4));
    for(unsigned n=0;n<144000;++n){double t=n/48000.,envelope=.35+.3*std::sin(2*3.141592653589793*3*t);double voice=envelope*(.4*std::sin(2*3.141592653589793*180*t)+.2*std::sin(2*3.141592653589793*720*t)+.1*std::sin(2*3.141592653589793*2160*t));double transient=(n%7200)<100?.2*std::exp(-(n%7200)/18.):0;write(int16_t((voice+transient)*32767));write(int16_t((voice-transient)*32767));}wav.close();
    for(int mode=1;mode<=3;++mode)for(double speed:{.25,.5,2.,4.}){sf::Project p;p.duration=.6;sf::Clip c;c.id=p.allocate();c.source=sx::Narrow(path.wstring());c.in=.2;c.duration=.6;c.speed=speed;c.params["stretch_mode"]={float(mode)};p.addTrack(sf::TrackKind::Audio).clips.push_back(c);p.validate();sf::MediaCache media;std::vector<float> whole;media.mix(p,0,28800,whole);double energy=0;for(float v:whole){if(!std::isfinite(v) || std::abs(v)>1)throw std::runtime_error("Invalid stretched PCM");energy+=v*v;}if(energy/whole.size()<.001)throw std::runtime_error("Stretch unexpectedly silent");++checks;sf::MediaCache pieces;std::vector<float> joined;for(unsigned n=0;n<28800;n+=514){std::vector<float> block;pieces.mix(p,n/48000.,std::min(514u,28800-n),block);joined.insert(joined.end(),block.begin(),block.end());}float difference=0;for(size_t n=0;n<whole.size();++n)difference=std::max(difference,std::abs(whole[n]-joined[n]));if(difference>.0001f)throw std::runtime_error("Time-stretch depends on chunk boundaries: "+std::to_string(difference));++checks;media.resetAudio();std::vector<float> repeated;media.mix(p,0,28800,repeated);if(repeated!=whole)throw std::runtime_error("Seek/reset changed stretched PCM");++checks;std::cout<<"Mode "<<mode<<", speed "<<speed<<": finite voiced/transient PCM, chunk and seek invariance"<<std::endl;}
    std::cout<<checks<<" audio quality checks passed"<<std::endl;
}catch(const std::exception &e){std::cerr<<e.what()<<std::endl;result=1;}MFShutdown();CoUninitialize();return result;}
